// =================================================================================================
// FILE: Maroos.Web/Components/Account/Shared/PasskeySubmit.razor.js
// ORIGIN: generated by the Blazor Identity template; Maroos uses it unchanged.
// PURPOSE: Browser side of passkeys. Defines the <passkey-submit> element that PasskeySubmit.razor renders.
// PROCESS (both operations):
//   1. Ask the server for options (POST /Account/PasskeyCreationOptions or /Account/PasskeyRequestOptions).
//   2. Hand them to the browser's passkey API (navigator.credentials.create / .get); the phone, laptop or
//      security key asks the user to confirm (fingerprint, face, PIN).
//   3. Put the result (or an error message) into the form and submit it; the page's C# checks it.
// App.razor loads this file as a module on every page.
// =================================================================================================
// browserSupportsPasskeys: true only if this browser has every passkey feature the code below uses.
const browserSupportsPasskeys =
    typeof navigator.credentials !== 'undefined' &&
    typeof window.PublicKeyCredential !== 'undefined' &&
    typeof window.PublicKeyCredential.parseCreationOptionsFromJSON === 'function' &&
    typeof window.PublicKeyCredential.parseRequestOptionsFromJSON === 'function';

// fetchWithErrorHandling: fetch that sends cookies (credentials: 'include') and throws on an error status.
async function fetchWithErrorHandling(url, options = {}) {
    const response = await fetch(url, {
        credentials: 'include',
        ...options
    });
    if (!response.ok) {
        const text = await response.text();
        console.error(text);
        throw new Error(`The server responded with status ${response.status}.`);
    }
    return response;
}

// createCredential: register a new passkey (Manage > Passkeys). The headers carry the antiforgery token.
async function createCredential(headers, signal) {
    const optionsResponse = await fetchWithErrorHandling('/Account/PasskeyCreationOptions', {
        method: 'POST',
        headers,
        signal,
    });
    const optionsJson = await optionsResponse.json();
    const options = PublicKeyCredential.parseCreationOptionsFromJSON(optionsJson);
    return await navigator.credentials.create({ publicKey: options, signal });
}

// requestCredential: sign in with an existing passkey. mediation 'conditional' lets the browser offer
// passkeys in the email box's autofill list instead of popping up a dialog.
async function requestCredential(email, mediation, headers, signal) {
    const optionsResponse = await fetchWithErrorHandling(`/Account/PasskeyRequestOptions?username=${email}`, {
        method: 'POST',
        headers,
        signal,
    });
    const optionsJson = await optionsResponse.json();
    const options = PublicKeyCredential.parseRequestOptionsFromJSON(optionsJson);
    return await navigator.credentials.get({ publicKey: options, mediation, signal });
}

// The <passkey-submit> custom element. formAssociated: it can put values into the form it's inside.
customElements.define('passkey-submit', class extends HTMLElement {
    static formAssociated = true;

    // connectedCallback: runs when the element appears on the page. It reads its settings from the attributes,
    // intercepts the form's submit when the passkey button was pressed, and tries passkey autofill.
    connectedCallback() {
        this.internals = this.attachInternals();
        this.attrs = {
            operation: this.getAttribute('operation'),
            name: this.getAttribute('name'),
            emailName: this.getAttribute('email-name'),
            requestTokenName: this.getAttribute('request-token-name'),
            requestTokenValue: this.getAttribute('request-token-value'),
        };

        this.internals.form.addEventListener('submit', (event) => {
            if (event.submitter?.name === '__passkeySubmit') {
                event.preventDefault();
                this.obtainAndSubmitCredential();
            }
        });

        this.tryAutofillPasskey();
    }

    // disconnectedCallback: the element left the page (e.g. navigation): cancel any passkey prompt still open.
    disconnectedCallback() {
        this.abortController?.abort();
    }

    // obtainCredential: Create or Request, depending on the operation attribute.
    async obtainCredential(useConditionalMediation, signal) {
        if (!browserSupportsPasskeys) {
            throw new Error('Some passkey features are missing. Please update your browser.');
        }

        const headers = {
            [this.attrs.requestTokenName]: this.attrs.requestTokenValue,
        };

        if (this.attrs.operation === 'Create') {
            return await createCredential(headers, signal);
        } else if (this.attrs.operation === 'Request') {
            const email = new FormData(this.internals.form).get(this.attrs.emailName);
            const mediation = useConditionalMediation ? 'conditional' : undefined;
            return await requestCredential(email, mediation, headers, signal);
        } else {
            throw new Error(`Unknown passkey operation '${this.attrs.operation}'.`);
        }
    }

    // obtainAndSubmitCredential: get the passkey (cancelling any earlier attempt), then submit the form with
    // either <Name>.CredentialJson or <Name>.Error, which bind to PasskeyInputModel on the server.
    async obtainAndSubmitCredential(useConditionalMediation = false) {
        this.abortController?.abort();
        this.abortController = new AbortController();
        const signal = this.abortController.signal;
        const formData = new FormData();
        try {
            const credential = await this.obtainCredential(useConditionalMediation, signal);
            const credentialJson = JSON.stringify(credential);
            formData.append(`${this.attrs.name}.CredentialJson`, credentialJson);
        } catch (error) {
            if (error.name === 'AbortError') {
                // The user explicitly canceled the operation - return without error.
                return;
            }
            console.error(error);
            if (useConditionalMediation) {
                // An error occurred during conditional mediation, which is not user-initiated.
                // We log the error in the console but do not relay it to the user.
                return;
            }
            const errorMessage = error.name === 'NotAllowedError'
                ? 'No passkey was provided by the authenticator.'
                : error.message;
            formData.append(`${this.attrs.name}.Error`, errorMessage);
        }
        this.internals.setFormValue(formData);
        this.internals.form.submit();
    }

    // tryAutofillPasskey: on the Login page, quietly offer saved passkeys in the browser's autofill if supported.
    async tryAutofillPasskey() {
        if (browserSupportsPasskeys && this.attrs.operation === 'Request' && await PublicKeyCredential.isConditionalMediationAvailable?.()) {
            await this.obtainAndSubmitCredential(/* useConditionalMediation */ true);
        }
    }
});
